        Question(7065, "Lequel de ces arbres est un conifère à feuilles caduques (il perd ses aiguilles en hiver) ?", listOf("Mélèze", "Sapin", "Pin", "Cèdre"), 0, "Nature", Difficulty.MEDIUM, explanation = "Contrairement à la plupart des conifères, le mélèze perd ses aiguilles en hiver, ce qui en fait une exception parmi les résineux."),
        Question(7066, "Quel est le plus grand mammifère terrestre ?", listOf("Éléphant d'Afrique", "Girafe", "Rhinocéros blanc", "Ours polaire"), 0, "Nature", Difficulty.MEDIUM, explanation = "L'éléphant d'Afrique est le plus grand mammifère terrestre, avec un poids pouvant atteindre 6 tonnes et une hauteur de 4 mètres au garrot."),
        Question(7067, "Quel terme désigne la couche de gaz entourant la Terre, essentielle à la vie et protégeant des rayons UV ?", listOf("Atmosphère", "Hydrosphère", "Lithosphère", "Biosphère"), 0, "Nature", Difficulty.MEDIUM, explanation = "L'atmosphère est l'enveloppe gazeuse qui entoure la Terre, composée principalement d'azote et d'oxygène. Elle filtre les rayons ultraviolets nocifs grâce à la couche d'ozone et régule la température."),
        Question(7068, "Quel animal marin, de la famille des cétacés, est surnommé 'licorne des mers' ?", listOf("Narval", "Béluga", "Dauphin", "Orque"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le narval possède une longue défense torsadée qui peut atteindre trois mètres, ce qui lui vaut ce surnom en référence à la licorne."),
        Question(7069, "Quelle plante, symbole de pureté dans certaines cultures, pousse souvent dans les étangs et a de grandes feuilles rondes ?", listOf("Nénuphar", "Roseau", "Lotus", "Jonc"), 2, "Nature", Difficulty.MEDIUM, explanation = "Le lotus est une plante aquatique sacrée dans l'hindouisme et le bouddhisme, symbolisant la pureté car elle émerge des eaux boueuses sans être souillée. Ses grandes feuilles rondes flottent à la surface des étangs."),
        Question(7070, "Quel type de nuage est associé aux orages et peut avoir une forme d'enclume ?", listOf("Cumulonimbus", "Stratus", "Cirrus", "Cumulus"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le cumulonimbus est un nuage de développement vertical intense, souvent porteur d'orages, de pluies fortes et de grêle. Son sommet s'étale en forme d'enclume lorsqu'il atteint la tropopause."),
        Question(7071, "Lequel de ces animaux est un marsupial ?", listOf("Kangourou", "Castor", "Écureuil", "Hérisson"), 0, "Nature", Difficulty.MEDIUM, explanation = "Les marsupiaux sont des mammifères qui portent leurs petits dans une poche ventrale, et le kangourou est l'exemple le plus emblématique de ce groupe."),
        Question(7072, "Quel est le nom du fruit du chêne ?", listOf("Gland", "Faîne", "Samare", "Noisette"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le fruit du chêne est un akène appelé gland, qui est une noix contenant une seule graine et protégée par une cupule."),
        Question(7073, "Quel courant océanique froid longe la côte ouest de l'Amérique du Sud et influence le phénomène El Niño ?", listOf("Courant de Humboldt", "Courant du Gulf Stream", "Courant de Kuroshio", "Courant des Canaries"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le Courant de Humboldt, aussi appelé courant du Pérou, remonte des eaux froides de l'Antarctique le long des côtes chilienne et péruvienne. Son affaiblissement périodique est un facteur clé du déclenchement du phénomène El Niño."),
        Question(7074, "Quel oiseau, incapable de voler, est le plus grand du monde ?", listOf("Autruche", "Émeu", "Manchot empereur", "Nandou"), 0, "Nature", Difficulty.MEDIUM, explanation = "L'autruche est le plus grand oiseau du monde, mesurant jusqu'à 2,7 mètres de haut, et ses ailes atrophiées l'empêchent de voler."),
        Question(7075, "Quel terme botanique désigne la partie femelle de la fleur ?", listOf("Pistil", "Étamine", "Pétale", "Sépale"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le pistil est l'organe reproducteur femelle de la fleur, composé du stigmate, du style et de l'ovaire."),
        Question(7076, "Dans la classification des climats de Köppen, quelle lettre désigne généralement un climat tempéré ?", listOf("C", "A", "B", "D"), 0, "Nature", Difficulty.MEDIUM, explanation = "La classification de Köppen utilise la lettre C pour les climats tempérés, caractérisés par une température moyenne du mois le plus froid entre -3°C et 18°C."),
        Question(7101, "Combien de sets faut-il gagner pour remporter un match de tennis en Grand Chelem messieurs ?", listOf("3", "4", "5", "2"), 0, "Sport", Difficulty.EASY, explanation = "Dans les tournois du Grand Chelem messieurs, les matchs se jouent au meilleur des cinq sets, ce qui signifie qu'il faut en remporter trois pour gagner."),
        Question(7102, "Quel pays a accueilli la Coupe du Monde de football 2022 ?", listOf("Arabie Saoudite", "Qatar", "Emirats Arabes Unis", "Bahrein"), 1, "Sport", Difficulty.EASY, explanation = "Le Qatar a accueilli la Coupe du Monde de football 2022, une première pour un pays du Moyen-Orient. Le tournoi s'est déroulé en novembre et décembre en raison des fortes chaleurs estivales."),
        Question(7103, "Combien de trous comprend un parcours standard de golf ?", listOf("9", "12", "18", "24"), 2, "Sport", Difficulty.EASY, explanation = "Un parcours standard de golf comporte 18 trous, une norme établie au 19e siècle par le Royal and Ancient Golf Club de St Andrews en Écosse."),
        Question(7104, "Quel est le record du monde du 100 metres en athletisme ?", listOf("9.58 secondes", "9.69 secondes", "9.72 secondes", "9.84 secondes"), 0, "Sport", Difficulty.MEDIUM, explanation = "Usain Bolt a établi ce record du monde le 16 août 2009 aux championnats du monde de Berlin, améliorant son propre record de 9,69 secondes."),
        Question(7105, "Quel club a remporte la premiere edition de la Ligue des Champions en 1992-93 ?", listOf("AC Milan", "Marseille", "FC Barcelone", "Ajax Amsterdam"), 1, "Sport", Difficulty.HARD, explanation = "Marseille a remporté la première édition de la Ligue des Champions en 1992-93, devenant ainsi le premier club français à gagner cette compétition."),
        Question(7106, "Combien de joueurs composent une equipe de rugby a XV ?", listOf("13", "15", "11", "7"), 1, "Sport", Difficulty.EASY, explanation = "Au rugby à XV, chaque équipe aligne 15 joueurs sur le terrain : 8 avants et 7 arrières."),
        Question(7107, "Quel boxeur reste invaincu avec un record de 50-0 ?", listOf("Mike Tyson", "Floyd Mayweather Jr.", "Muhammad Ali", "Manny Pacquiao"), 1, "Sport", Difficulty.MEDIUM, explanation = "Floyd Mayweather Jr. a pris sa retraite en 2017 avec un bilan parfait de 50 victoires et 0 défaite, incluant des succès contre Manny Pacquiao et Conor McGregor."),
        Question(7109, "Quel cycliste detient le record de 5 victoires consecutives au Tour de France ?", listOf("Eddy Merckx", "Miguel Indurain", "Bernard Hinault", "Jacques Anquetil"), 1, "Sport", Difficulty.HARD, explanation = "Miguel Indurain a remporté le Tour de France de 1991 à 1995, devenant le premier coureur à réaliser cinq victoires consécutives."),
        Question(7110, "En handball, combien de joueurs de champ sont sur le terrain par equipe ?", listOf("5", "6", "7", "8"), 1, "Sport", Difficulty.EASY, explanation = "Au handball, chaque équipe aligne 6 joueurs de champ et un gardien de but, soit 7 joueurs au total sur le terrain."),
        Question(7111, "Quel pays a remporte le premier Championnat d'Europe de football en 1960 ?", listOf("France", "Allemagne", "Union Sovietique", "Espagne"), 2, "Sport", Difficulty.HARD, explanation = "L'URSS a remporté le premier Euro en 1960 en battant la Yougoslavie 2-1 en finale à Paris."),
        Question(7112, "Quel pilote de F1 est surnomme The Iceman ?", listOf("Mika Hakkinen", "Kimi Raikkonen", "Nico Rosberg", "Valtteri Bottas"), 1, "Sport", Difficulty.MEDIUM, explanation = "Kimi Raikkonen a gagné ce surnom pour son sang-froid légendaire et son attitude impassible, même sous pression, durant sa carrière en Formule 1."),
        Question(7113, "Quel sport se joue avec un volant (shuttlecock) ?", listOf("Tennis de table", "Badminton", "Squash", "Pelote basque"), 1, "Sport", Difficulty.EASY, explanation = "Le badminton utilise un volant, aussi appelé shuttlecock, qui est un projectile conique en plumes ou en plastique, frappé avec une raquette à travers un filet."),
        Question(7114, "Quel pays a domine les JO 2008 en nombre de medailles d'or ?", listOf("Etats-Unis", "Russie", "Chine", "Grande-Bretagne"), 2, "Sport", Difficulty.MEDIUM, explanation = "La Chine a dominé les Jeux olympiques de Pékin en 2008 en remportant 48 médailles d'or, profitant de l'effet de jouer à domicile."),
        Question(7115, "Quelle equipe nationale a remporte la Coupe du Monde de football 2018 ?", listOf("Croatie", "Bresil", "France", "Allemagne"), 2, "Sport", Difficulty.EASY, explanation = "L'équipe de France a battu la Croatie 4-2 en finale le 15 juillet 2018 à Moscou, remportant ainsi son deuxième titre mondial après 1998."),
        Question(7201, "Combien de chromosomes possede une cellule humaine normale ?", listOf("23", "44", "46", "48"), 2, "Science", Difficulty.MEDIUM, explanation = "Chaque cellule humaine normale contient 23 paires de chromosomes, soit 46 au total, héritées des deux parents."),
        Question(7202, "Quel metal est le meilleur conducteur electrique ?", listOf("Or", "Cuivre", "Argent", "Aluminium"), 2, "Science", Difficulty.HARD, explanation = "L'argent possède la plus haute conductivité électrique de tous les métaux à température ambiante, ce qui le rend idéal pour les contacts électriques et les circuits haute performance."),
        Question(7203, "Quel organe du corps humain produit la bile ?", listOf("Pancreas", "Estomac", "Foie", "Rate"), 2, "Science", Difficulty.MEDIUM, explanation = "La bile est produite par le foie, puis stockée dans la vésicule biliaire. Elle aide à la digestion des graisses dans l'intestin grêle."),
        Question(7204, "Quelle est la temperature du zero absolu en Celsius ?", listOf("-273.15", "- 300", "-250", "-200"), 0, "Science", Difficulty.HARD, explanation = "Le zéro absolu correspond à la température théorique la plus basse possible, où l'agitation moléculaire cesse. En degrés Celsius, cette limite est fixée à -273,15°C, servant de base à l'échelle Kelvin."),
        Question(7205, "Quel est le nombre atomique de l'hydrogene ?", listOf("0", "1", "2", "3"), 1, "Science", Difficulty.EASY, explanation = "Le nombre atomique correspond au nombre de protons dans le noyau. L'hydrogène possède un seul proton, d'où son nombre atomique 1."),
        Question(7206, "Combien de temps met la lumiere du Soleil pour atteindre la Terre ?", listOf("1 minute", "8 minutes", "15 minutes", "30 secondes"), 1, "Science", Difficulty.MEDIUM, explanation = "La lumière du Soleil parcourt environ 150 millions de kilomètres à la vitesse de 300 000 km/s, ce qui prend environ 8 minutes et 20 secondes."),
        Question(7207, "Qui a invente le telephone ?", listOf("Thomas Edison", "Nikola Tesla", "Alexander Graham Bell", "Guglielmo Marconi"), 2, "Science", Difficulty.EASY, explanation = "Alexander Graham Bell a déposé le brevet du téléphone en 1876, bien que d'autres inventeurs comme Elisha Gray aient travaillé sur des dispositifs similaires à la même époque."),
        Question(7209, "Quelle vitamine est synthetisee par la peau sous l'effet du soleil ?", listOf("Vitamine A", "Vitamine B12", "Vitamine C", "Vitamine D"), 3, "Science", Difficulty.MEDIUM, explanation = "La vitamine D est synthétisée par la peau lors de l'exposition aux rayons UVB du soleil, un processus essentiel pour la fixation du calcium et la santé osseuse."),
        Question(7210, "Combien de planetes compose le systeme solaire ?", listOf("7", "8", "9", "10"), 1, "Science", Difficulty.EASY, explanation = "Le système solaire compte huit planètes reconnues depuis 2006, quand Pluton a été reclassée comme planète naine par l'Union astronomique internationale."),
        Question(7211, "Quel element chimique porte le numero atomique 79 ?", listOf("Argent", "Platine", "Or", "Cuivre"), 2, "Science", Difficulty.EXPERT, explanation = "L'or est l'élément de numéro atomique 79, un métal précieux utilisé en bijouterie et comme réserve de valeur."),
        Question(7212, "Quel type de roche se forme par le refroidissement du magma ?", listOf("Sedimentaire", "Metamorphique", "Magmatique", "Calcaire"), 2, "Science", Difficulty.MEDIUM, explanation = "Les roches magmatiques, aussi appelées ignées, résultent de la solidification du magma en fusion en profondeur ou en surface."),
        Question(7213, "Quel scientifique a decouvert la penicilline ?", listOf("Louis Pasteur", "Alexander Fleming", "Robert Koch", "Joseph Lister"), 1, "Science", Difficulty.MEDIUM, explanation = "Alexander Fleming a découvert la pénicilline en 1928 en observant qu’une moisissure inhibait la croissance de bactéries dans une boîte de Pétri."),
        Question(7215, "Quel phenomene physique explique l'arc-en-ciel ?", listOf("Reflection", "Refraction", "Diffraction", "Absorption"), 1, "Science", Difficulty.MEDIUM, explanation = "La lumière blanche du soleil se décompose en ses couleurs spectrales lorsqu'elle traverse les gouttes d'eau, un phénomène appelé réfraction."),
        Question(7301, "En quelle annee Christophe Colomb a-t-il atteint les Ameriques ?", listOf("1498", "1492", "1500", "1488"), 1, "Histoire", Difficulty.EASY, explanation = "Christophe Colomb, cherchant une route vers les Indes par l'ouest, débarqua aux Bahamas le 12 octobre 1492, marquant le premier contact européen durable avec les Amériques."),
        Question(7302, "Quel pharaon est associe a la plus grande pyramide de Gizeh ?", listOf("Toutankhamon", "Ramses II", "Kheops", "Akhenaton"), 2, "Histoire", Difficulty.MEDIUM, explanation = "La pyramide de Khéops, aussi appelée Grande Pyramide, est la plus ancienne et la plus grande des pyramides de Gizeh, construite sous le règne du pharaon Khéops (IVe dynastie)."),
        Question(7303, "Quelle guerre a oppose le Nord et le Sud des Etats-Unis ?", listOf("Guerre d'Independance", "Guerre de Secession", "Guerre du Vietnam", "Guerre hispano-americaine"), 1, "Histoire", Difficulty.EASY, explanation = "La guerre de Sécession (1861-1865) opposa les États du Nord (Union) à ceux du Sud (Confédérés) principalement sur les questions de l'esclavage et des droits des États."),
        Question(7304, "Quel empereur romain a legalise le christianisme en 313 ?", listOf("Auguste", "Neron", "Constantin", "Marc Aurele"), 2, "Histoire", Difficulty.HARD, explanation = "Par l'édit de Milan en 313, Constantin accorde la liberté de culte aux chrétiens, mettant fin aux persécutions dans l'Empire romain."),
        Question(7305, "Quel pays a lance la premiere bombe atomique en temps de guerre ?", listOf("Union Sovietique", "Etats-Unis", "Allemagne", "Japon"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Les États-Unis ont largué la première bombe atomique sur Hiroshima le 6 août 1945, suivie de celle de Nagasaki trois jours plus tard, précipitant la fin de la Seconde Guerre mondiale."),
        Question(7306, "En quelle annee a ete signee la Declaration d'independance americaine ?", listOf("1789", "1776", "1804", "1763"), 1, "Histoire", Difficulty.MEDIUM, explanation = "La Déclaration d'indépendance des États-Unis a été adoptée par le Congrès continental le 4 juillet 1776, proclamant la séparation des treize colonies de la Grande-Bretagne."),
        Question(7307, "Quel explorateur portugais a atteint l'Inde par la mer en 1498 ?", listOf("Christophe Colomb", "Magellan", "Vasco de Gama", "Bartolomeu Dias"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Vasco de Gama fut le premier Européen à atteindre l'Inde par voie maritime en contournant l'Afrique, ouvrant ainsi la route des épices pour le Portugal."),
        Question(7308, "Quel evenement a marque le debut de la Revolution francaise en 1789 ?", listOf("Execution de Louis XVI", "Prise de la Bastille", "Serment du Jeu de Paume", "Fuite a Varennes"), 1, "Histoire", Difficulty.EASY, explanation = "Le 14 juillet 1789, des Parisiens en colère prennent d'assaut la forteresse de la Bastille, symbole de l'autorité royale, pour récupérer des armes et des munitions. Cet événement déclenche la Révolution française en marquant la première grande insurrection populaire contre la monarchie."),
        Question(7309, "Quel roi anglais avait six epouses ?", listOf("Richard III", "Henri VIII", "Edouard VI", "Jacques Ier"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Henri VIII d'Angleterre est connu pour avoir eu six épouses, dont il répudia ou fit exécuter certaines pour assurer une descendance mâle."),
        Question(7311, "Quel traite a cree l'Union europeenne en 1992 ?", listOf("Traite de Rome", "Traite de Maastricht", "Traite de Lisbonne", "Traite de Nice"), 1, "Histoire", Difficulty.HARD, explanation = "Le traité de Maastricht, signé en 1992, a institué l'Union européenne en établissant trois piliers, dont la citoyenneté européenne et les critères pour la monnaie unique."),
        Question(7312, "Quel mur a divise Berlin de 1961 a 1989 ?", listOf("Mur de l'Atlantique", "Ligne Maginot", "Mur de Berlin", "Rideau de fer"), 2, "Histoire", Difficulty.EASY, explanation = "Construit par la RDA, le Mur de Berlin séparait physiquement et idéologiquement Berlin-Est de Berlin-Ouest pendant la Guerre froide."),
        Question(7313, "Quel empire s'est effondre en 1453 avec la chute de Constantinople ?", listOf("Empire romain", "Empire ottoman", "Empire byzantin", "Empire perse"), 2, "Histoire", Difficulty.HARD, explanation = "La chute de Constantinople en 1453, après un siège mené par les Ottomans, marque la fin de l'Empire byzantin, dernier vestige de l'Empire romain d'Orient."),
        Question(7314, "Quelle bataille navale de 1805 fut la derniere victoire de Nelson ?", listOf("Aboukir", "Trafalgar", "Jutland", "Lepante"), 1, "Histoire", Difficulty.HARD, explanation = "La bataille de Trafalgar, livrée le 21 octobre 1805, opposa la flotte britannique à la flotte franco-espagnole. Nelson y trouva la mort, mais remporta une victoire décisive qui assura la suprématie navale britannique."),
        Question(7315, "Quel president americain a aboli l'esclavage ?", listOf("George Washington", "Thomas Jefferson", "Abraham Lincoln", "Theodore Roosevelt"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Abraham Lincoln a promulgué le 13e amendement en 1865, abolissant définitivement l'esclavage aux États-Unis après la guerre de Sécession."),
        Question(7401, "Quelle est la capitale de la Nouvelle-Zelande ?", listOf("Auckland", "Wellington", "Christchurch", "Hamilton"), 1, "Geographie", Difficulty.MEDIUM, explanation = "Wellington est la capitale de la Nouvelle-Zélande depuis 1865, remplaçant Auckland. Elle abrite le Parlement et les institutions gouvernementales du pays."),
        Question(7402, "Quel est le plus grand pays du monde en superficie ?", listOf("Canada", "Chine", "Etats-Unis", "Russie"), 3, "Geographie", Difficulty.EASY, explanation = "La Russie s'étend sur environ 17,1 millions de kilomètres carrés, couvrant l'Europe de l'Est et l'Asie du Nord."),
        Question(7403, "Quel fleuve traverse Londres ?", listOf("Seine", "Rhin", "Tamise", "Danube"), 2, "Geographie", Difficulty.EASY, explanation = "La Tamise est le principal fleuve traversant Londres, s'écoulant d'ouest en est jusqu'à la mer du Nord. Elle est au cœur de l'histoire et de l'économie de la ville depuis l'époque romaine."),
        Question(7404, "Quel pays possede le plus grand nombre d'iles au monde ?", listOf("Philippines", "Indonesie", "Suede", "Japon"), 2, "Geographie", Difficulty.HARD, explanation = "La Suède compte environ 267 570 îles, dont la plupart sont inhabitées, ce qui en fait le pays avec le plus grand nombre d'îles au monde."),
        Question(7405, "Quelle est la mer la plus salee du monde ?", listOf("Mer Morte", "Mer Rouge", "Mer Caspienne", "Mer Mediterranee"), 0, "Geographie", Difficulty.MEDIUM, explanation = "La Mer Morte est la plus salée du monde avec une salinité d'environ 34%, soit près de dix fois celle des océans, ce qui permet de flotter facilement à sa surface."),
        Question(7406, "Quel est le point le plus profond des oceans ?", listOf("Fosse de Porto Rico", "Fosse des Mariannes", "Fosse des Tonga", "Fosse de Java"), 1, "Geographie", Difficulty.MEDIUM, explanation = "La fosse des Mariannes, située dans l'océan Pacifique, atteint environ 11 034 mètres de profondeur à son point nommé Challenger Deep."),
        Question(7407, "Combien de continents compte la Terre ?", listOf("5", "6", "7", "8"), 2, "Geographie", Difficulty.EASY, explanation = "Le modèle des sept continents (Afrique, Amériques, Antarctique, Asie, Europe, Océanie) est le plus enseigné dans les pays francophones et anglo-saxons."),
        Question(7408, "Quel pays a pour capitale Reykjavik ?", listOf("Norvege", "Finlande", "Islande", "Danemark"), 2, "Geographie", Difficulty.MEDIUM, explanation = "Reykjavik est la capitale et la plus grande ville d'Islande, située sur la côte sud-ouest du pays."),
        Question(7409, "Quel desert se trouve en Amerique du Sud ?", listOf("Sahara", "Gobi", "Atacama", "Kalahari"), 2, "Geographie", Difficulty.HARD, explanation = "Le désert d'Atacama, situé principalement au Chili, est le plus aride du monde et constitue le principal désert d'Amérique du Sud."),
        Question(7410, "Quel est le plus grand lac d'eau douce du monde par superficie ?", listOf("Lac Baikal", "Lac Victoria", "Lac Superieur", "Lac Titicaca"), 2, "Geographie", Difficulty.HARD, explanation = "Le lac Supérieur, situé entre les États-Unis et le Canada, est le plus grand lac d'eau douce du monde avec une superficie d'environ 82 100 km². Il fait partie des Grands Lacs d'Amérique du Nord."),
        Question(7411, "Quelle chaine de montagnes separe l'Europe de l'Asie ?", listOf("Alpes", "Caucase", "Oural", "Carpates"), 2, "Geographie", Difficulty.MEDIUM, explanation = "L'Oural forme une barrière naturelle traditionnellement reconnue comme la limite entre l'Europe et l'Asie, s'étendant de l'océan Arctique jusqu'au Kazakhstan."),
        Question(7412, "Quel pays d'Afrique a pour capitale Nairobi ?", listOf("Ouganda", "Tanzanie", "Kenya", "Ethiopie"), 2, "Geographie", Difficulty.MEDIUM, explanation = "Nairobi est la capitale du Kenya, située dans le sud du pays. Elle est le centre économique et politique du Kenya."),
        Question(7413, "Quel est le plus petit pays du monde ?", listOf("Monaco", "Vatican", "Saint-Marin", "Liechtenstein"), 1, "Geographie", Difficulty.EASY, explanation = "Le Vatican, enclavé dans Rome, s'étend sur seulement 0,44 km², ce qui en fait le plus petit État indépendant du monde en superficie et en population."),
        Question(7414, "Sur quel continent se trouve le lac Titicaca ?", listOf("Afrique", "Asie", "Amerique du Sud", "Europe"), 2, "Geographie", Difficulty.MEDIUM, explanation = "Le lac Titicaca est situé dans la cordillère des Andes, à la frontière entre le Pérou et la Bolivie, ce qui le place en Amérique du Sud."),
        Question(7415, "Quel pays a la plus grande population au monde ?", listOf("Inde", "Chine", "Etats-Unis", "Indonesie"), 0, "Geographie", Difficulty.EASY, explanation = "L'Inde a dépassé la Chine en 2023 pour devenir le pays le plus peuplé du monde, avec environ 1,4 milliard d'habitants."),
        Question(7501, "Quel realisateur a cree la saga Star Wars ?", listOf("Steven Spielberg", "George Lucas", "James Cameron", "Ridley Scott"), 1, "Culture", Difficulty.EASY, explanation = "George Lucas a écrit et réalisé le premier film Star Wars en 1977, lançant ainsi la saga."),
        Question(7502, "Quel groupe de rock a sorti l'album The Dark Side of the Moon ?", listOf("Led Zeppelin", "The Rolling Stones", "Pink Floyd", "The Who"), 2, "Culture", Difficulty.MEDIUM, explanation = "Pink Floyd a sorti The Dark Side of the Moon en 1973, un album conceptuel devenu l'un des plus vendus de l'histoire du rock."),
        Question(7503, "Quel manga suit les aventures de Monkey D. Luffy ?", listOf("Naruto", "Dragon Ball", "One Piece", "Bleach"), 2, "Culture", Difficulty.EASY, explanation = "One Piece est un manga d'aventure créé par Eiichiro Oda, publié depuis 1997, qui raconte la quête de Monkey D. Luffy pour devenir le roi des pirates."),
        Question(7504, "Quel ecrivain francais a ecrit Le Petit Prince ?", listOf("Victor Hugo", "Albert Camus", "Antoine de Saint-Exupery", "Marcel Proust"), 2, "Culture", Difficulty.EASY, explanation = "Antoine de Saint-Exupéry, aviateur et écrivain, publie Le Petit Prince en 1943, une œuvre philosophique sous forme de conte pour enfants."),
        Question(7505, "Quel jeu video a popularise le genre battle royale en 2017 ?", listOf("Fortnite", "PUBG", "Apex Legends", "Call of Duty Warzone"), 1, "Culture", Difficulty.MEDIUM, explanation = "PUBG, sorti en accès anticipé en mars 2017, a imposé le format du battle royale avec son gameplay réaliste et ses parties à 100 joueurs."),
        Question(7506, "Quel peintre espagnol est connu pour sa periode bleue ?", listOf("Salvador Dali", "Pablo Picasso", "Joan Miro", "Francisco Goya"), 1, "Culture", Difficulty.MEDIUM, explanation = "Picasso a traversé une période bleue entre 1901 et 1904, marquée par des tons froids et des thèmes mélancoliques, après le suicide de son ami Carlos Casagemas."),
        Question(7507, "Quelle serie anime met en scene des combats de Shinigami ?", listOf("Naruto", "Bleach", "One Piece", "Dragon Ball Z"), 1, "Culture", Difficulty.MEDIUM, explanation = "Bleach suit les aventures d'Ichigo Kurosaki, un adolescent qui devient Shinigami (dieu de la mort) et combat des esprits maléfiques appelés Hollows."),
        Question(7508, "Quel film Pixar met en scene un robot solitaire sur Terre ?", listOf("Les Indestructibles", "Ratatouille", "WALL-E", "La-Haut"), 2, "Culture", Difficulty.EASY, explanation = "WALL-E, sorti en 2008, suit un petit robot laissé seul sur une Terre polluée et abandonnée par les humains, chargé de compacter les déchets."),
        Question(7509, "Quel auteur britannique a cree Sherlock Holmes ?", listOf("Agatha Christie", "Arthur Conan Doyle", "J.R.R. Tolkien", "Charles Dickens"), 1, "Culture", Difficulty.MEDIUM, explanation = "Arthur Conan Doyle, médecin et écrivain écossais, a créé le détective Sherlock Holmes en 1887 pour son roman \"Une étude en rouge\"."),
        Question(7510, "Quel jeu video met en scene un plombier qui sauve une princesse ?", listOf("Sonic", "Super Mario Bros.", "Donkey Kong", "Mega Man"), 1, "Culture", Difficulty.EASY, explanation = "Super Mario Bros., sorti en 1985 sur NES, a popularisé le personnage de Mario, un plombier moustachu, dans sa quête pour sauver la princesse Peach du méchant Bowser."),
        Question(7511, "Quel rappeur americain a sorti l'album The Marshall Mathers LP ?", listOf("Jay-Z", "Kanye West", "Eminem", "50 Cent"), 2, "Culture", Difficulty.MEDIUM, explanation = "Eminem a sorti The Marshall Mathers LP en 2000, un album nommé d'après son vrai nom, Marshall Mathers."),
        Question(7512, "Quelle BD belge met en scene un reporter avec une houppe ?", listOf("Spirou", "Tintin", "Lucky Luke", "Gaston Lagaffe"), 1, "Culture", Difficulty.EASY, explanation = "Tintin, créé par Hergé en 1929, est un reporter à la célèbre mèche de cheveux (houppe) dans la série de bande dessinée belge Les Aventures de Tintin."),
        Question(7513, "Quel artiste a peint le plafond de la chapelle Sixtine ?", listOf("Raphael", "Leonard de Vinci", "Michel-Ange", "Le Caravage"), 2, "Culture", Difficulty.MEDIUM, explanation = "Michel-Ange a réalisé cette fresque monumentale entre 1508 et 1512, commandée par le pape Jules II, représentant des scènes de la Genèse."),
        Question(7514, "Quel film de 1999 explore le concept de realite simulee ?", listOf("Inception", "The Matrix", "Blade Runner", "Dark City"), 1, "Culture", Difficulty.MEDIUM, explanation = "The Matrix, réalisé par les Wachowski, présente un monde où la réalité est une simulation informatique créée par des machines pour contrôler l'humanité."),
        Question(7515, "Quel auteur a ecrit la saga Harry Potter ?", listOf("Stephen King", "J.R.R. Tolkien", "J.K. Rowling", "George R.R. Martin"), 2, "Culture", Difficulty.EASY, explanation = "J.K. Rowling est l'auteure britannique qui a créé la saga Harry Potter, publiée entre 1997 et 2007."),
        Question(7601, "Quel est l'animal terrestre le plus rapide ?", listOf("Lion", "Guepard", "Antilope", "Loup"), 1, "Nature", Difficulty.EASY, explanation = "Le guépard peut atteindre des pointes de vitesse allant jusqu'à 110 km/h sur de courtes distances, ce qui en fait le mammifère terrestre le plus rapide au monde."),
        Question(7602, "Combien de pattes possede une araignee ?", listOf("6", "8", "10", "12"), 1, "Nature", Difficulty.EASY, explanation = "Les araignées appartiennent à la classe des arachnides, qui se distinguent des insectes par huit pattes, contre six pour ces derniers."),
        Question(7603, "Quel est le plus grand animal ayant jamais vecu sur Terre ?", listOf("Elephant d'Afrique", "Diplodocus", "Baleine bleue", "Megalodon"), 2, "Nature", Difficulty.MEDIUM, explanation = "La baleine bleue peut atteindre plus de 30 mètres de long et peser jusqu'à 200 tonnes, dépassant ainsi tous les dinosaures connus en taille et en masse."),
        Question(7604, "Quel est le plus grand ocean du monde ?", listOf("Atlantique", "Indien", "Arctique", "Pacifique"), 3, "Nature", Difficulty.EASY, explanation = "L'océan Pacifique couvre environ 165 millions de kilomètres carrés, soit plus du tiers de la surface terrestre, ce qui en fait le plus vaste océan du monde."),
        Question(7605, "Quel animal produit du miel ?", listOf("Guepe", "Bourdon", "Abeille", "Frelon"), 2, "Nature", Difficulty.EASY, explanation = "Les abeilles butinent le nectar des fleurs, le transforment dans leur jabot et le stockent dans les alvéoles de la ruche pour produire du miel."),
        Question(7606, "Combien de coeurs possede une pieuvre ?", listOf("1", "2", "3", "4"), 2, "Nature", Difficulty.HARD, explanation = "Les pieuvres ont trois cœurs : deux branchiaux qui pompent le sang vers les branchies, et un systémique qui le distribue au reste du corps."),
        Question(7607, "Quel arbre produit des glands ?", listOf("Hetre", "Chene", "Erable", "Bouleau"), 1, "Nature", Difficulty.EASY, explanation = "Le chêne est l'arbre qui produit les glands, ses fruits caractéristiques qui servent de nourriture à de nombreux animaux comme les écureuils et les sangliers."),
        Question(7608, "Quel est le serpent le plus long du monde ?", listOf("Anaconda", "Python reticule", "Cobra royal", "Mamba noir"), 1, "Nature", Difficulty.HARD, explanation = "Le python réticulé peut atteindre plus de 10 mètres de long, ce qui en fait le serpent le plus long jamais mesuré, bien que l'anaconda vert soit plus lourd."),
        Question(7609, "Combien d'estomacs possede une vache ?", listOf("1", "2", "3", "4"), 3, "Nature", Difficulty.MEDIUM, explanation = "Les vaches sont des ruminants, leur système digestif comporte quatre compartiments : la panse, le bonnet, le feuillet et la caillette."),
        Question(7610, "Quel phenomene naturel est mesure sur l'echelle de Richter ?", listOf("Ouragan", "Tornade", "Seisme", "Tsunami"), 2, "Nature", Difficulty.EASY, explanation = "L'échelle de Richter quantifie l'énergie libérée par un séisme, en mesurant l'amplitude des ondes sismiques enregistrées par les sismographes."),
        Question(7611, "Quel est l'oiseau le plus rapide en vol pique ?", listOf("Aigle royal", "Faucon pelerin", "Condor", "Albatros"), 1, "Nature", Difficulty.MEDIUM, explanation = "Le faucon pèlerin atteint des vitesses de plus de 300 km/h en piqué, ce qui en fait l'animal le plus rapide du monde en vol."),
        Question(7612, "Quel type de foret se trouve pres de l'equateur ?", listOf("Boreale", "Temperee", "Tropicale", "Mediterraneenne"), 2, "Nature", Difficulty.EASY, explanation = "Les forêts tropicales sont situées dans la zone équatoriale, où le climat chaud et humide favorise une végétation dense et luxuriante."),
        Question(7613, "Quel mammifere peut voler ?", listOf("Ecureuil volant", "Chauve-souris", "Polatouche", "Colugo"), 1, "Nature", Difficulty.EASY, explanation = "Les chauves-souris sont les seuls mammifères capables de vol actif, grâce à leurs ailes membraneuses soutenues par des os allongés."),
        Question(7614, "Quel est le plus grand recif corallien du monde ?", listOf("Recif de Belize", "Grande Barriere de corail", "Recif de Nouvelle-Caledonie", "Recif des Maldives"), 1, "Nature", Difficulty.MEDIUM, explanation = "La Grande Barrière de corail, située au large de l'Australie, s'étend sur plus de 2 300 kilomètres et est visible depuis l'espace."),
        Question(7615, "Quel animal est connu pour sa capacite a regenerer ses membres ?", listOf("Lezard", "Etoile de mer", "Salamandre", "Axolotl"), 3, "Nature", Difficulty.HARD, explanation = "L'axolotl, une salamandre néoténique du Mexique, possède une capacité unique de régénération complète de ses membres, de sa moelle épinière et même de parties de son cerveau.")
    )
}
